    with x:
        cats=['站上 MA20','低於/等於 MA20']
        vals=[int((df.close>df.ma20).sum()),int((df.close<=df.ma20).sum())]
        fig=go.Figure(go.Pie(labels=cats,values=vals,hole=.68,marker_colors=['#28c9a6','#df6574']))
