        fig=go.Figure(go.Bar(x=rsi.index.astype(str),y=rsi.values,marker_color=['#df6574','#58758e','#28c9a6','#e5b85d']))
        fig.update_layout(title='RSI 區間分布',height=350,template='plotly_dark',paper_bgcolor='#101a28',plot_bgcolor='#101a28',margin=dict(l=15,r=15,t=50,b=15))
        st.plotly_chart(fig,use_container_width=True,config={'displayModeBar':False})

